const body = $json.body || {};
const currentScreen = String(body.current_screen || body.screen || '').trim();
const leadType = String(body.lead_type || body.model_type || 'particular').trim().toLowerCase();
const p5Competencia = String(body.p5_competencia || '').trim().toLowerCase();

let nextScreen = String(body.next_screen || '').trim();
const data = { ...body, lead_type: leadType };

if (!nextScreen) {
  if (currentScreen === 'P_DOS_TIEMPO_COMPRA') {
    if (leadType === 'comercial') {
      nextScreen = 'P_CUATRO_FORMA_PAGO';
      data.p3_test_drive = '';
    } else {
      nextScreen = 'P_TRES_TEST_DRIVE';
    }
  } else if (currentScreen === 'P_CINCO_COMPETENCIA') {
    if (p5Competencia === 'si') {
      nextScreen = 'P_CINCO_DETALLE_COMPETENCIA';
    } else {
      nextScreen = 'P_SEIS_COTIZACION';
      data.p5_competencia_detalle = '';
    }
  } else if (currentScreen === 'P_CINCO_DETALLE_COMPETENCIA') {
    nextScreen = 'P_SEIS_COTIZACION';
  } else if (currentScreen === 'P_SEIS_COTIZACION') {
    nextScreen = 'P_SIETE_COMENTARIO';
  } else {
    nextScreen = 'WELCOME_SCREEN';
  }
}

return [{
  json: {
    version: '7.3',
    screen: nextScreen,
    data,
    debug: {
      current_screen: currentScreen,
      lead_type: leadType,
      p5_competencia: p5Competencia
    }
  }
}];
